/** Public dictionary retirement contracts, independent of the persisted reference-count representation. */
class LmdbReferenceCountContractTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SHARED = VF.createIRI("urn:reference-contract:shared");
	private static final String NAMESPACE_PREFIX = "urn:reference-contract:namespace:";
	private static final long FIXTURE_TIMEOUT_SECONDS = 10;
	private final ConcurrentCleaner cleaner = new ConcurrentCleaner();

	@TempDir
	Path directory;
	private ValueStore store;

	@BeforeEach
	void openStore() throws IOException {
		store = new ValueStore(directory.resolve("values").toFile(), new LmdbStoreConfig());
	}

	@AfterEach
	void closeStore() throws IOException {
		store.close();
	}

	@ParameterizedTest
	@EnumSource(Dependency.class)
	void referencesSurviveSeparateCommits(Dependency dependency) throws Exception {
		Value[] values = dependency.fixtureValues();
		store.startTransaction(true);
		long[] ids = new long[values.length];
		for (int i = 0; i < 3; i++) {
			ids[i] = store.storeValue(values[i]);
		}
		store.commit();
		store.startTransaction(true);
		ids[3] = store.storeValue(values[3]);
		store.commit();

		store.startTransaction(true);
		Set<Long> nextIds = new HashSet<>();
		store.gcIds(Set.of(ids[3]), nextIds);
		assertProtectedDependency(dependency, nextIds);
		store.commit();
		assertSurvivors(values, ids, 3);
		store.close();
		openStore();
		assertSurvivors(values, ids, 3);
	}

	@ParameterizedTest
	@EnumSource(Dependency.class)
	void rolledBackReferencesDoNotChangeCommittedDependencies(Dependency dependency) throws Exception {
		Value[] values = dependency.fixtureValues();
		store.startTransaction(true);
		long[] ids = new long[values.length];
		for (int i = 0; i < 3; i++) {
			ids[i] = store.storeValue(values[i]);
		}
		store.commit();
		store.startTransaction(true);
		store.storeValue(values[3]);
		store.rollback();

		store.startTransaction(true);
		Set<Long> nextIds = new HashSet<>();
		store.gcIds(Set.of(ids[2]), nextIds);
		assertProtectedDependency(dependency, nextIds);
		store.commit();
		assertSurvivors(values, ids, 2);
		assertEquals(LmdbValue.UNKNOWN_ID, store.getId(values[3]), "The rolled-back value must remain absent");
	}

	@Test
	void cachedNewDatatypeReferencePreventsRetirement() throws Exception {
		store.startTransaction(true);
		Value literal = VF.createLiteral("new datatype reference", SHARED);
		long literalId = store.storeValue(literal);
		long datatypeId = store.getId(SHARED);
		Set<Long> nextIds = new HashSet<>();
		store.gcIds(Set.of(datatypeId), nextIds);
		assertTrue(nextIds.isEmpty(), "A referenced datatype must not release its namespace dependency");
		store.commit();
		assertEquals(datatypeId, store.getId(SHARED), "A positive new reference must protect the datatype mapping");
		assertEquals(literal, store.getValue(literalId));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void duplicateCollectionDecrementsDependenciesOnce(boolean sameBatch) throws Exception {
		Value removed = VF.createLiteral("removed reference", SHARED);
		Value surviving = VF.createLiteral("surviving reference", SHARED);
		store.startTransaction(true);
		long removedId = store.storeValue(removed);
		long survivingId = store.storeValue(surviving);
		store.commit();
		LmdbValue retainedOriginal = store.getLazyValue(removedId);

		store.startTransaction(true);
		Set<Long> nextIds = new HashSet<>();
		store.gcIds(sameBatch ? Arrays.asList(removedId, removedId) : Set.of(removedId), nextIds);
		assertTrue(nextIds.isEmpty(), "Retiring one owner must retain the surviving owner's datatype reference");
		store.commit();
		if (!sameBatch) {
			// The duplicate is supplied while the retired ID still names its original retained reverse record.
			store.startTransaction(true);
			store.gcIds(Set.of(removedId), nextIds);
			assertTrue(nextIds.isEmpty(), "A retired forward mapping must not release its datatype twice");
			store.commit();
		}
		assertEquals(survivingId, store.getId(surviving));
		assertEquals(surviving, store.getValue(survivingId));
		Reference.reachabilityFence(retainedOriginal);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nestedDependenciesRemainLiveUntilLastParentRetires(boolean separateCommits) throws Exception {
		TripleTerm inner = VF.createTripleTerm(SHARED, SHARED, SHARED);
		TripleTerm outer = VF.createTripleTerm(SHARED, SHARED, inner);
		store.startTransaction(true);
		long innerId = store.storeValue(inner);
		if (separateCommits) {
			store.commit();
			store.startTransaction(true);
		}
		long outerId = store.storeValue(outer);
		long sharedId = store.getId(SHARED);
		store.commit();

		store.startTransaction(true);
		Set<Long> nextIds = new HashSet<>();
		store.gcIds(Set.of(innerId), nextIds);
		assertTrue(nextIds.isEmpty(), "A live parent must protect its nested term's component references");
		store.commit();
		assertEquals(innerId, store.getId(inner), "A referenced nested term must retain its active forward mapping");
		assertEquals(outer, store.getValue(outerId));

		store.startTransaction(true);
		store.gcIds(Set.of(outerId), nextIds);
		assertEquals(Set.of(innerId), nextIds, "Only the last parent releases the nested term");
		Set<Long> componentIds = new HashSet<>();
		store.gcIds(nextIds, componentIds);
		assertEquals(Set.of(sharedId), componentIds, "Repeated subject/predicate/object roles are separate references");
		store.commit();
		assertEquals(LmdbValue.UNKNOWN_ID, store.getId(inner));
		assertEquals(LmdbValue.UNKNOWN_ID, store.getId(outer));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void duplicateRetirementPreservesReusedAssociation(boolean tripleTerm) throws Exception {
		Value anchor = VF.createBNode("later-retirement-cohort-anchor");
		Value original = tripleTerm ? VF.createTripleTerm(SHARED, SHARED, VF.createLiteral("original object"))
				: VF.createBNode("original owner");
		Value replacement = tripleTerm ? VF.createTripleTerm(SHARED, SHARED, VF.createLiteral("replacement object"))
				: VF.createBNode("replacement owner");
		store.startTransaction(true);
		long anchorId = store.storeValue(anchor);
		if (tripleTerm) {
			// Precommit every replacement component so no new child allocation can consume the parent's free ID.
			store.storeValue(SHARED);
			store.storeValue(((TripleTerm) original).getObject());
			store.storeValue(((TripleTerm) replacement).getObject());
		}
		long originalId = store.storeValue(original);
		store.commit();
		LmdbValue originalReady = store.getLazyValue(originalId);
		CountDownLatch firstCollected = trackCollection(originalReady.getValueStoreRevision());
		readFully(originalReady);

		retireOnly(originalId);
		LmdbValue laterAnchor = store.getLazyValue(anchorId);
		CountDownLatch laterCollected = trackCollection(laterAnchor.getValueStoreRevision());
		// Both retirement intents precede ID reuse; the second still addresses the original association.
		retireOnly(originalId);
		awaitCollectionAndCleanup(firstCollected);
		evictRetiredValues();
		store.startTransaction(true);
		long replacementId = store.storeValue(replacement);
		assertEquals(originalId, replacementId, "The first retirement cohort must actually free this compound ID");
		store.commit();
		assertEquals(replacement, store.getValue(replacementId));
		Reference.reachabilityFence(laterAnchor);
		laterAnchor.init();
		awaitCollectionAndCleanup(laterCollected);
		evictRetiredValues();
		assertEquals(replacementId, store.getId(replacement), "A later duplicate intent must preserve the new owner");
		assertEquals(replacement, store.getValue(replacementId),
				"Reclaiming the later cohort must not delete a replacement's native record");
		Reference.reachabilityFence(originalReady);
	}

	private void assertProtectedDependency(Dependency dependency, Set<Long> nextIds) throws IOException {
		if (dependency == Dependency.TRIPLE_COMPONENT) {
			assertFalse(nextIds.contains(store.getId(SHARED)),
					"Three surviving terms must retain their shared predicate");
		} else {
			assertTrue(nextIds.isEmpty(), "Three surviving values must retain their shared " + dependency);
		}
	}

	private void assertSurvivors(Value[] values, long[] ids, int count) throws IOException {
		for (int i = 0; i < count; i++) {
			assertEquals(ids[i], store.getId(values[i]), "A surviving value must keep its native forward association");
			assertEquals(values[i], store.getValue(ids[i]), "A surviving value's dependencies must remain resolvable");
		}
	}

	private void retireOnly(long id) throws IOException {
		store.startTransaction(true);
		store.gcIds(Set.of(id), new HashSet<>());
		store.commit();
	}

	private void evictRetiredValues() throws IOException {
		store.forceEvictionOfValues();
		store.startTransaction(true);
		store.commit();
	}

	private CountDownLatch trackCollection(Object referent) {
		CountDownLatch collected = new CountDownLatch(1);
		cleaner.register(referent, collected::countDown);
		return collected;
	}

	private void awaitCollectionAndCleanup(CountDownLatch collected) throws InterruptedException {
		awaitCollection(collected);
		// A subsequent action on the same ConcurrentCleaner drains the store's epoch-retirement action too.
		awaitCollection(trackCollection(new Object()));
	}

	private void awaitCollection(CountDownLatch collected) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(FIXTURE_TIMEOUT_SECONDS);
		while (collected.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			collected.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals(0, collected.getCount(), "The released Lazy cohort must complete its actual cleaner action");
	}

	private static void readFully(Value value) {
		value.stringValue();
		if (value instanceof TripleTerm term) {
			readFully(term.getSubject());
			readFully(term.getPredicate());
			readFully(term.getObject());
		} else if (value instanceof Literal literal) {
			readFully(literal.getDatatype());
		}
	}

	private enum Dependency {
		DATATYPE,
		NAMESPACE,
		TRIPLE_COMPONENT;

		Value[] fixtureValues() {
			Value[] values = new Value[4];
			for (int i = 0; i < values.length; i++) {
				values[i] = switch (this) {
				case DATATYPE -> VF.createLiteral("reference " + i, SHARED);
				case NAMESPACE -> VF.createIRI(NAMESPACE_PREFIX, "reference" + i);
				case TRIPLE_COMPONENT -> VF.createTripleTerm(VF.createBNode("reference" + i), SHARED,
						VF.createLiteral("object " + i));
				};
			}
			return values;
		}
	}
}
